# R golden fixtures for gaply_core's one-way ANOVA as an analysis
# (Research OS, Phase 8G, decisions 312 to 316, capability
# stats.analyze.one_way_anova).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_anova_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R, car or
# effectsize is copied into Gaply. Needs the CRAN packages car (for
# leveneTest) and effectsize (decision 67), for reference fixtures only.
#
# Writes, next to this script:
#   * data_*.csv: one synthetic dataset per case (a two-line '#' header, then
#     `id,y,g`), each READ BACK with read.csv(na.strings = "", g as character)
#     and everything computed on what was read;
#   * cases.tsv: each case's file, the levels it includes (0-based indices in
#     code-point order, or "all"), and its missing codes;
#   * expected.tsv: R's answer for every case, one statistic per row
#     (case, key, value), the value as %.17g, "NC" where Gaply must say "not
#     computable" (decision 312's list, decided here from the values, as Gaply
#     decides it), and "NA" where R itself returns NaN (ptukey and qtukey
#     below df 2);
#   * t_quantile.tsv: qt(1 - p/2, df) over a grid, for stats_dist::t_quantile;
#   * f_upper.tsv: pf(F, df1, df2, lower.tail = FALSE) over df1 up to 49, df2
#     up to 1e5 and fractional df2, each F placed by qf at a target p
#     (decision 316).
#
# The levels are the distinct non-missing g in code-point order,
# sort(method = "radix"), whatever the locale: Gaply's order (decision 78).
# Each pair (i, j), i before j in that order, is level i minus level j.
#
# Where each number comes from:
#   * the ANOVA table and F: aov(y ~ f), its p from pf(lower.tail = FALSE);
#     for ties_offset every model is fitted on y - 1e9, exact for its integer
#     values, because aov on the raw values loses about 5e-8 (measured: SS
#     between 25.199998709 where it is 25.2, and oneway.test's F 1.4e-8 off);
#     checked against oneway.test(var.equal = TRUE);
#   * Welch's ANOVA: oneway.test(var.equal = FALSE);
#   * Levene: car::leveneTest(y ~ f, center = mean) and center = median;
#   * eta squared, SS between / SS total, and omega squared, (SS between -
#     (k - 1) MS within) / (SS total + MS within), from aov's table; effectsize's
#     eta_squared and omega_squared (partial = FALSE) cross-checked where
#     omega is 0 or more (effectsize truncates omega at 0, decision 315);
#   * Tukey HSD: TukeyHSD(aov), which reports a pair as later minus earlier:
#     here its diff is negated and its lwr and upr swapped and negated. It
#     gives no q or SE: q = |diff| / sqrt((MS within / 2)(1/ni + 1/nj)) and
#     SE = sqrt(MS within (1/ni + 1/nj)) are computed here by decision 312's
#     formulas;
#   * Games-Howell has no base R function: it is computed here from its
#     formula, with Welch's df per pair, ptukey and qtukey. THE SAME FORMULA
#     IS WRITTEN TWICE, here and in gaply_core, so this is a check of the
#     arithmetic, not an independent method; ptukey and qtukey are R's;
#   * Bonferroni: t, SE and the interval qt(1 - 0.05/(2m), N - k) are
#     computed here (THE SAME FORMULA WRITTEN TWICE), and the p is checked
#     against pairwise.t.test(p.adjust.method = "bonferroni", pool.sd = TRUE),
#     stopping on any difference over 1e-12 relative.
#
# The 100,000-row case big5 has no CSV: its rows are a formula both sides
# compute exactly, row i (0-based) in group i mod 5 (A to E) with
# y = ((i * 7919) mod 10007) / 100 + (i mod 5) * 0.5.

suppressPackageStartupMessages({
  library(car)
  library(effectsize)
})

here <- local({
  a <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f)) dirname(normalizePath(f)) else getwd()
})
setwd(here)

HEADER <- c(
  "# Synthetic data for gaply_core's one-way ANOVA R golden fixtures (Research OS, Phase 8G).",
  "# Generated by /usr/local/bin/Rscript make_anova_fixtures.R (do not edit by hand)."
)
fmt <- function(x) if (is.character(x)) x else if (is.na(x)) "NA" else sprintf("%.17g", x)

write_data <- function(name, y, g) {
  path <- paste0("data_", name, ".csv")
  ys <- ifelse(is.na(y), "", format(y, digits = 15, trim = TRUE, scientific = FALSE))
  gs <- ifelse(is.na(g), "", g)
  writeLines(c(HEADER, "id,y,g", paste(seq_along(ys), ys, gs, sep = ",")), path)
  d <- read.csv(path, comment.char = "#", na.strings = "", colClasses = c("integer", "numeric", "character"))
  d
}

cases <- list()
expected <- character()
emit <- function(case, key, value) {
  expected <<- c(expected, paste(case, key, fmt(value), sep = "\t"))
}

radix_levels <- function(g) sort(unique(g[!is.na(g)]), method = "radix")

analyse <- function(case, d, include = NULL, missing_codes = numeric(), shift = 0) {
  levs_all <- radix_levels(d$g)
  inc <- if (is.null(include)) seq_along(levs_all) - 1 else include
  levs <- levs_all[inc + 1]
  keep <- !is.na(d$g) & d$g %in% levs & !is.na(d$y) & !(d$y %in% missing_codes)
  emit(case, "excluded.missing_group", sum(is.na(d$g)))
  emit(case, "excluded.other_level", sum(!is.na(d$g) & !(d$g %in% levs)))
  emit(case, "excluded.missing_outcome", sum(!is.na(d$g) & d$g %in% levs & is.na(d$y)))
  emit(case, "excluded.missing_code", sum(!is.na(d$g) & d$g %in% levs & !is.na(d$y) & d$y %in% missing_codes))
  y <- d$y[keep]
  f <- factor(d$g[keep], levels = levs)
  # Every model is fitted on y - shift: exact for ties_offset's integers,
  # and every statistic but the group table's location is unchanged by it.
  ys <- y - shift
  k <- length(levs)
  ns <- as.numeric(table(f))
  N <- sum(ns)
  emit(case, "k", k)
  emit(case, "rows_used", N)
  if (any(ns < 2)) {
    emit(case, "refused", paste0("group_too_small:", which(ns < 2)[1] - 1, ":", ns[ns < 2][1]))
    return(invisible())
  }
  means <- tapply(ys, f, mean)
  vars <- tapply(ys, f, var)
  for (i in seq_len(k)) {
    yi <- y[f == levs[i]]
    se <- sd(yi) / sqrt(ns[i])
    h <- qt(0.975, ns[i] - 1) * se
    p <- paste0("group.", i - 1, ".")
    emit(case, paste0(p, "n"), ns[i])
    emit(case, paste0(p, "mean"), mean(yi))
    emit(case, paste0(p, "sd"), sd(yi))
    emit(case, paste0(p, "se"), se)
    emit(case, paste0(p, "ci_lower"), mean(yi) - h)
    emit(case, paste0(p, "ci_upper"), mean(yi) + h)
    emit(case, paste0(p, "min"), min(yi))
    emit(case, paste0(p, "max"), max(yi))
  }
  model <- aov(ys ~ f)
  tab <- summary(model)[[1]]
  ss_b <- tab[["Sum Sq"]][1]
  ss_w <- tab[["Sum Sq"]][2]
  ss_t <- ss_b + ss_w
  ms_w <- ss_w / (N - k)
  ss_total_zero <- all(ys == ys[1])
  ms_within_zero <- all(vars == 0)
  nc <- function(key) emit(case, key, "NC")
  if (ss_total_zero) {
    for (key in c("anova.ss_between", "anova.ss_within", "anova.ss_total", "anova.ms_between",
                  "anova.ms_within", "anova.f", "anova.p", "eta_sq", "omega_sq")) nc(key)
  } else {
    emit(case, "anova.ss_between", ss_b)
    emit(case, "anova.ss_within", ss_w)
    emit(case, "anova.ss_total", ss_t)
    emit(case, "anova.ms_between", ss_b / (k - 1))
    emit(case, "anova.ms_within", ms_w)
    emit(case, "eta_sq", ss_b / ss_t)
    if (ms_within_zero) {
      nc("anova.f"); nc("anova.p"); nc("omega_sq")
    } else {
      fv <- tab[["F value"]][1]
      emit(case, "anova.f", fv)
      emit(case, "anova.p", pf(fv, k - 1, N - k, lower.tail = FALSE))
      ow <- oneway.test(ys ~ f, var.equal = TRUE)
      stopifnot(abs(ow$statistic - fv) <= 1e-12 * abs(fv))
      omega <- (ss_b - (k - 1) * ms_w) / (ss_t + ms_w)
      emit(case, "omega_sq", omega)
      emit(case, "eta_sq_effectsize", eta_squared(model, partial = FALSE, verbose = FALSE)$Eta2[1])
      if (omega >= 0) {
        emit(case, "omega_sq_effectsize", omega_squared(model, partial = FALSE, verbose = FALSE)$Omega2[1])
      }
    }
  }
  if (!ss_total_zero) {
    emit(case, "anova.df_between", k - 1)
    emit(case, "anova.df_within", N - k)
  }
  dead <- ss_total_zero || ms_within_zero
  # Welch: not computable when any group's variance is 0 (decision 312).
  if (dead || any(vars == 0)) {
    for (key in c("welch.f", "welch.df1", "welch.df2", "welch.p")) nc(key)
  } else {
    w <- oneway.test(ys ~ f, var.equal = FALSE)
    emit(case, "welch.f", unname(w$statistic))
    emit(case, "welch.df1", unname(w$parameter[1]))
    emit(case, "welch.df2", unname(w$parameter[2]))
    emit(case, "welch.p", w$p.value)
  }
  # Levene, each centre on its own: not computable when its ANOVA's MS
  # within is 0, every group's absolute deviations equal within the group.
  for (centre in c("mean", "median")) {
    cf <- if (centre == "mean") mean else median
    dev <- abs(ys - ave(ys, f, FUN = cf))
    # Equal within the group: by construction in a group of two (both
    # centres are its mean, and its two deviations are one number, though
    # rounding can leave them an ulp apart: R's leveneTest then gives an F
    # of 8.3e30 on data_n2.csv), and otherwise bit for bit.
    devconst <- all(tapply(seq_along(dev), f, function(ix) length(ix) == 2 || all(dev[ix] == dev[ix][1])))
    key <- paste0("levene_", centre, ".")
    if (dead || devconst) {
      for (s in c("f", "df1", "df2", "p")) nc(paste0(key, s))
    } else {
      lt <- leveneTest(ys ~ f, center = cf)
      emit(case, paste0(key, "f"), lt[["F value"]][1])
      emit(case, paste0(key, "df1"), lt[["Df"]][1])
      emit(case, paste0(key, "df2"), lt[["Df"]][2])
      emit(case, paste0(key, "p"), lt[["Pr(>F)"]][1])
    }
  }
  if (dead) {
    emit(case, "posthoc", "NC")
    return(invisible())
  }
  m <- k * (k - 1) / 2
  tk <- TukeyHSD(model, conf.level = 0.95)$f
  pw <- pairwise.t.test(ys, f, p.adjust.method = "bonferroni", pool.sd = TRUE)$p.value
  tq_crit <- qtukey(0.95, k, N - k)
  t_crit <- qt(1 - 0.05 / (2 * m), N - k)
  for (i in seq_len(k - 1)) for (j in (i + 1):k) {
    pair <- paste0(i - 1, "-", j - 1)
    diff <- unname(means[i] - means[j])
    # Tukey (Tukey-Kramer)
    se <- sqrt(ms_w * (1 / ns[i] + 1 / ns[j]))
    row <- tk[paste(levs[j], levs[i], sep = "-"), ]
    stopifnot(abs(-row[["diff"]] - diff) <= 1e-9 * max(1, abs(diff)))
    p <- paste0("tukey.", pair, ".")
    emit(case, paste0(p, "diff"), diff)
    emit(case, paste0(p, "se"), se)
    emit(case, paste0(p, "q"), abs(diff) / sqrt((ms_w / 2) * (1 / ns[i] + 1 / ns[j])))
    emit(case, paste0(p, "df"), N - k)
    emit(case, paste0(p, "p"), row[["p adj"]])
    emit(case, paste0(p, "ci_lower"), -row[["upr"]])
    emit(case, paste0(p, "ci_upper"), -row[["lwr"]])
    emit(case, paste0(p, "crit"), tq_crit)
    # Games-Howell, from its formula (written twice: here and in gaply_core)
    p <- paste0("gh.", pair, ".")
    if (vars[i] == 0 && vars[j] == 0) {
      for (s in c("diff", "se", "q", "df", "p", "ci_lower", "ci_upper")) nc(paste0(p, s))
    } else {
      a <- vars[i] / ns[i]
      b <- vars[j] / ns[j]
      se_gh <- sqrt(a + b)
      df_gh <- (a + b)^2 / (a^2 / (ns[i] - 1) + b^2 / (ns[j] - 1))
      q_gh <- sqrt(2) * abs(diff) / se_gh
      p_gh <- suppressWarnings(ptukey(q_gh, k, df_gh, lower.tail = FALSE))
      crit <- suppressWarnings(qtukey(0.95, k, df_gh))
      emit(case, paste0(p, "diff"), diff)
      emit(case, paste0(p, "se"), unname(se_gh))
      emit(case, paste0(p, "q"), unname(q_gh))
      emit(case, paste0(p, "df"), unname(df_gh))
      emit(case, paste0(p, "p"), unname(p_gh))
      emit(case, paste0(p, "ci_lower"), unname(diff - crit * se_gh / sqrt(2)))
      emit(case, paste0(p, "ci_upper"), unname(diff + crit * se_gh / sqrt(2)))
      emit(case, paste0(p, "crit"), unname(crit))
    }
    # Bonferroni, pooled MS within, df N - k (written twice; p checked)
    t <- diff / se
    pb <- min(1, m * 2 * pt(-abs(t), N - k))
    pr <- pw[levs[j], levs[i]]
    stopifnot(abs(pb - pr) <= 1e-12 * max(pr, 1e-300))
    p <- paste0("bonf.", pair, ".")
    emit(case, paste0(p, "diff"), diff)
    emit(case, paste0(p, "se"), se)
    emit(case, paste0(p, "t"), t)
    emit(case, paste0(p, "df"), N - k)
    emit(case, paste0(p, "p"), pb)
    emit(case, paste0(p, "ci_lower"), diff - t_crit * se)
    emit(case, paste0(p, "ci_upper"), diff + t_crit * se)
  }
}

add_case <- function(case, name, y, g, include = NULL, missing_codes = numeric(), file = NULL, shift = 0) {
  d <- if (is.null(file)) write_data(name, y, g) else file
  cases[[length(cases) + 1]] <<- c(
    case, if (is.null(name)) "-" else paste0("data_", name, ".csv"),
    if (is.null(include)) "all" else paste(include, collapse = " "),
    if (length(missing_codes)) paste(missing_codes, collapse = " ") else "-"
  )
  analyse(case, d, include, missing_codes, shift)
  invisible(d)
}

r3 <- function(x) round(x, 3)
set.seed(8007)

# k = 2, equal n
add_case("k2", "k2", r3(c(rnorm(12, 10, 2), rnorm(12, 12, 2))), rep(c("a", "b"), each = 12))
# k = 3, unequal n and unequal variances
ns <- c(8, 13, 21)
add_case("k3_unequal", "k3_unequal",
         r3(c(rnorm(8, 5, 1), rnorm(13, 6, 2.5), rnorm(21, 8, 4))),
         rep(c("lo", "mid", "hi"), ns))
# k = 5, equal n
d5 <- add_case("k5_equal", "k5_equal", r3(rnorm(75, rep(c(3, 3.5, 4, 3.2, 5), each = 15), 1)),
               rep(c("e1", "e2", "e3", "e4", "e5"), each = 15))
# the same data, levels 0, 2 and 3 only: the others are other_level
cases[[length(cases) + 1]] <- c("k5_left_out", "data_k5_equal.csv", "0 2 3", "-")
analyse("k5_left_out", d5, include = c(0, 2, 3))
# k = 10, unequal n and variances
n10 <- 4:13
add_case("k10", "k10",
         r3(unlist(lapply(1:10, function(i) rnorm(n10[i], i / 2, 0.5 + i / 5)))),
         rep(sprintf("g%02d", 1:10), n10))
# k = 50, unequal n (3 to 6)
n50 <- 3 + (0:49) %% 4
add_case("k50", "k50",
         r3(unlist(lapply(1:50, function(i) rnorm(n50[i], 10 + (i %% 7) / 3, 1 + (i %% 3) / 2)))),
         rep(sprintf("L%02d", 1:50), n50))
# level names whose code-point order differs from a locale's: B Z _m a b
cp <- c("b", "B", "a", "Z", "_m")
add_case("codepoint", "codepoint",
         r3(unlist(lapply(1:5, function(i) rnorm(6 + i, c(4, 6, 5, 3, 7)[i], 1)))),
         rep(cp, 6 + 1:5))
# ties and a 1e9 offset
add_case("ties_offset", "ties_offset",
         1e9 + c(1, 1, 2, 2, 2, 3, 2, 3, 3, 3, 4, 4, 5, 5, 5, 6, 1, 1, 1, 2),
         rep(c("p", "q", "r", "s"), each = 5), shift = 1e9)
# a group of one value: refused before any run
add_case("group_of_one", "group_of_one", c(1.5, 2.5, 3.5, 4, 5, 6.5, 9), c("a", "a", "a", "b", "c", "c", "c"))
# missing cells: an empty outcome, an empty group, and a missing code -99
add_case("missing", "missing",
         c(4.1, NA, 5.2, 6.3, -99, 5.5, 7.1, 7.9, NA, 8.8, 6.6, 3.9, 4.4, -99, 5.0),
         c("x", "x", "x", "x", "x", "y", "y", "y", "y", "y", NA, "z", "z", "z", "z"),
         missing_codes = -99)
# the outcome constant across all rows: only the group table
add_case("outcome_constant", "outcome_constant", rep(7, 9), rep(c("a", "b", "c"), each = 3))
# every group constant, with different means: MS within 0
add_case("all_groups_constant", "all_groups_constant",
         c(3, 3, 3, 5, 5, 9, 9, 9, 9), c("a", "a", "a", "b", "b", "c", "c", "c", "c"))
# two groups of variance 0, two not: Welch not computable, Games-Howell's
# a-b pair not computable, the other pairs computed
add_case("some_constant", "some_constant",
         c(2, 2, 2, 4, 4, 4, 4, 3.1, 4.7, 5.2, 6.9, 5.5, 6.1, 7.4, 6.8, 8.0),
         c("a", "a", "a", "b", "b", "b", "b", "c", "c", "c", "c", "d", "d", "d", "d", "d"))
# every group of n = 2: Levene not computable on both centres
add_case("n2", "n2", c(1.2, 2.9, 4.1, 4.4, 2.0, 6.5, 7.7, 7.9), rep(c("a", "b", "c", "d"), each = 2))
# means nearly equal: omega squared negative
add_case("negative_omega", "negative_omega",
         c(5.1, 4.8, 6.2, 5.5, 4.9, 5.0, 5.3, 6.1, 4.7, 5.6, 5.2, 4.9, 5.8, 5.4, 5.0),
         rep(c("a", "b", "c"), each = 5))
# a very large F: p far below what 1 - cdf can give
add_case("large_f", "large_f",
         c(1.00, 1.01, 0.99, 1.02, 0.98, 5.00, 5.01, 4.99, 5.02, 4.98, 9.00, 9.01, 8.99, 9.02, 8.98),
         rep(c("a", "b", "c"), each = 5))
# 100,000 rows in 5 groups, by formula (no CSV)
i <- 0:99999
big <- data.frame(id = i + 1, y = ((i * 7919) %% 10007) / 100 + (i %% 5) * 0.5,
                  g = c("A", "B", "C", "D", "E")[i %% 5 + 1], stringsAsFactors = FALSE)
cases[[length(cases) + 1]] <- c("big5", "-", "all", "-")
analyse("big5", big)

writeLines(c("# written by: /usr/local/bin/Rscript make_anova_fixtures.R", paste0("# ", R.version.string,
                                                                          ", car ", packageVersion("car"),
                                                                          ", effectsize ", packageVersion("effectsize")),
             "case\tfile\tinclude\tmissing_codes",
             vapply(cases, paste, "", collapse = "\t")), "cases.tsv")
writeLines(c("# written by: /usr/local/bin/Rscript make_anova_fixtures.R", paste0("# ", R.version.string,
                                                                          ", car ", packageVersion("car"),
                                                                          ", effectsize ", packageVersion("effectsize")),
             "case\tkey\tvalue", expected), "expected.tsv")

# t_quantile: qt(1 - p/2, df), p two-sided
tq <- character()
for (df in c(1, 1.5, 2, 3, 5, 10, 30, 100, 1e3, 5e3, 1e4, 1.5e4, 5e4, 1e5, 1e6, 1e7)) {
  for (p in c(0.05, 0.05 / 3, 0.005, 0.05 / 45, 0.05 / 190, 0.05 / 1225, 1e-6, 1e-10)) {
    tq <- c(tq, sprintf("%.17g\t%.17g\t%.17g", p, df, qt(1 - p / 2, df)))
  }
}
writeLines(c("# written by: /usr/local/bin/Rscript make_anova_fixtures.R", paste0("# ", R.version.string),
             "p\tdf\tqt", tq), "t_quantile.tsv")

# f_upper: pf at F placed by qf
fu <- character()
for (df1 in c(2, 4, 9, 19, 49)) {
  for (df2 in c(2.5, 7.3, 30, 117.6, 1e3, 1e4, 2.5e4, 1e5)) {
    for (p in c(0.5, 0.05, 1e-3, 1e-6, 1e-10, 1e-30)) {
      f <- qf(p, df1, df2, lower.tail = FALSE)
      if (!is.finite(f)) next
      fu <- c(fu, sprintf("%.17g\t%.17g\t%.17g\t%.17g", f, df1, df2, pf(f, df1, df2, lower.tail = FALSE)))
    }
  }
}
writeLines(c("# written by: /usr/local/bin/Rscript make_anova_fixtures.R", paste0("# ", R.version.string),
             "f\tdf1\tdf2\tpf"), "f_upper.tsv")
cat(fu, file = "f_upper.tsv", sep = "\n", append = TRUE)
cat("cases", length(cases), "expected rows", length(expected), "t_quantile rows", length(tq), "f_upper rows", length(fu), "\n")
